 using System.Collections.Generic;
 using System.Reflection;
 using Contoso.Pricing;
 using Microsoft.VisualStudio.TestTools.UnitTesting;

 namespace Contoso.Pricing.Tests;

 [TestClass]
 public sealed class PriceCalculatorTests
 {
     private PriceCalculator _calculator = null!;

     [TestInitialize]
     public void Setup() => _calculator = new PriceCalculator();

     // ─── CalculateTotal: DataRow tests ───────────────────────────────────

     [TestMethod]
     [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
     [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
     [DataRow(25.00, 2, 0.10, 55.00, DisplayName = "Two items, 10% tax")]
     [DataRow(99.99, 3, 0.08, 323.97, DisplayName = "Three items, 8% tax")]
     [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price yields zero total")]
     [DataRow(15.50, 0, 0.15, 0.00, DisplayName = "Zero quantity yields zero total")]
     [DataRow(100.00, 1, 1.0, 200.00, DisplayName = "100% tax doubles the price")]
     public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
         double unitPrice, int quantity, double taxRate, double expectedTotal)
     {
         var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

         Assert.AreEqual((decimal)expectedTotal, result, $"Expected {expectedTotal} but got {result}");
     }

     // ─── CalculateTotal: DynamicData tests ───────────────────────────────

     [TestMethod]
     [DynamicData(nameof(CalculateTotalEdgeCases), DynamicDataSourceType.Method)]
     public void CalculateTotal_EdgeCases_ReturnsExpectedTotal(
         decimal unitPrice, int quantity, decimal taxRate, decimal expectedTotal)
     {
         var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

         Assert.AreEqual(expectedTotal, result);
     }

     private static IEnumerable<object[]> CalculateTotalEdgeCases()
     {
         yield return new object[] { 0.01m, 1, 0.0m, 0.01m };       // Minimum meaningful price
         yield return new object[] { 9999.99m, 100, 0.25m, 1249998.75m }; // Large order with tax
         yield return new object[] { 1.00m, 1, 0.0m, 1.00m };       // Identity case
         yield return new object[] { 33.33m, 3, 0.07m, 106.99m };   // Rounding scenario
     }

     // ─── CalculateTotal: Invalid input tests ─────────────────────────────

     [TestMethod]
     [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
     [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
     [DataRow(10.00, 1, -0.01, DisplayName = "Negative tax rate throws")]
     [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1 throws")]
     public void CalculateTotal_WithInvalidInputs_ThrowsArgumentOutOfRangeException(
         double unitPrice, int quantity, double taxRate)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
     }

     // ─── ApplyDiscount: DataRow tests ────────────────────────────────────

     [TestMethod]
     [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount returns original price")]
     [DataRow(100.00, 10.0, 90.00, DisplayName = "10% discount")]
     [DataRow(100.00, 50.0, 50.00, DisplayName = "50% discount")]
     [DataRow(100.00, 100.0, 0.00, DisplayName = "100% discount returns zero")]
     [DataRow(49.99, 25.0, 37.4925, DisplayName = "Non-round price with 25% discount")]
     [DataRow(0.00, 50.0, 0.00, DisplayName = "Zero price stays zero after discount")]
     public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
         double price, double discountPercent, double expectedPrice)
     {
         var result = _calculator.ApplyDiscount((decimal)price, (decimal)discountPercent);

         Assert.AreEqual((decimal)expectedPrice, result);
     }

     // ─── ApplyDiscount: DynamicData with display name ────────────────────

     [TestMethod]
     [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method,
         DynamicDataDisplayName = nameof(GetDiscountTestDisplayName))]
     public void ApplyDiscount_WithInvalidDiscount_ThrowsArgumentOutOfRangeException(
         decimal price, decimal discountPercent)
     {
         Assert.ThrowsException<ArgumentOutOfRangeException>(
             () => _calculator.ApplyDiscount(price, discountPercent));
     }

     private static IEnumerable<object[]> InvalidDiscountCases()
     {
         yield return new object[] { 100m, -1m };    // Below zero
         yield return new object[] { 100m, 101m };   // Above 100
         yield return new object[] { 50m, -0.01m };  // Barely below zero
         yield return new object[] { 50m, 100.01m }; // Barely above 100
     }

     public static string GetDiscountTestDisplayName(MethodInfo methodInfo, object[] data)
         => $"{methodInfo.Name} (price: {data[0]}, discount: {data[1]}%)";
 }

